def answer_question(image, question="woman on the right"):
    image_patch = ImagePatch(image)
    woman_patches = image_patch.find("woman")

    if not woman_patches:
        return "No woman found."

    sorted_women = sorted(woman_patches, key=lambda w: abs(w.right - image.shape[1] // 2))

    closest_woman = sorted_women[0]
    gender = closest_woman.simple_query("What is the gender?")

    if gender.lower() != "woman":
        return f"No woman found."

    location = closest_woman.simple_query("Where is she located?")

    if "right" in location.lower():
        return "The woman is on the right."
    elif "left" in location.lower():
        return "The woman is on the left."
    else:
        return "The woman is in the center."

